document.addEventListener("DOMContentLoaded",()=>{const createLi=document.getElementById("nav-create-store");const signinLi=document.getElementById("nav-signin");const signinLink=document.getElementById("nav-signin-link");const hasStore=typeof Auth!=="undefined"&&!!Auth.getToken();const hasCustomer=typeof CustomerAuth!=="undefined"&&!!CustomerAuth.getToken();if(createLi&&hasStore)createLi.hidden=true;if(hasCustomer){if(signinLink){signinLink.textContent="Account";signinLink.setAttribute("href","customer-dashboard.html")}}else if(signinLink&&hasStore){signinLink.addEventListener("click",e=>{e.preventDefault();showLoginChooser()})}});function showLoginChooser(){if(document.getElementById("login-chooser"))return;const overlay=document.createElement("div");overlay.id="login-chooser";overlay.className="login-chooser-overlay";overlay.innerHTML='<div class="login-chooser-card" role="dialog" aria-modal="true" aria-label="Choose how to log in">'+"<h2>Log In</h2>"+'<a class="btn btn-primary btn-block" href="customer-login.html">Customer Login</a>'+'<a class="btn btn-block" href="owner/login.html">Seller Login</a>'+'<button type="button" class="btn btn-block login-chooser-cancel">Cancel</button>'+"</div>";document.body.appendChild(overlay);overlay.addEventListener("click",e=>{if(e.target===overlay||e.target.classList.contains("login-chooser-cancel"))overlay.remove()});document.addEventListener("keydown",function onEsc(ev){if(ev.key==="Escape"){overlay.remove();document.removeEventListener("keydown",onEsc)}})}